def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c - 1] == row[c + 1] and row[c] != row[c - 1]:
                # The task's marked motif is a matching pair separated by a gap.
                # Infer the fill color from the observed 4 _ 4 -> 4 2 4 pattern.
                if row[c - 1] == 4:
                    out[r][c] = 2
                elif row[c - 1] == 8:
                    out[r][c] = 2
    return out
